/** Arrows that point the way text reads, so they flip in right-to-left languages. */
private val Mirrored = setOf("ArrowBack", "ArrowForward", "ChevronLeft", "ChevronRight", "Send", "Forum", "ChatBubble")

private fun icon(name: String, symbols: Boolean, vararg paths: String): ImageVector {
    val size = if (symbols) 960f else 24f
    return ImageVector.Builder(name, 24.dp, 24.dp, size, size, autoMirror = name in Mirrored).apply {
        addGroup(translationY = if (symbols) 960f else 0f)
        paths.forEach { addPath(addPathNodes(it), fill = SolidColor(Color.Black)) }
        clearGroup()
    }.build()
}
